#[test]
fn timedelta_matches_cpython() {
    let t = TimeDelta::new(0, 0, 0).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (0, 0, 0));
    assert_eq!(t.__repr__(), "datetime.timedelta(0)");
    assert_eq!(t.__str__(), "0:00:00");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x0000000000000000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(t.__neg__().unwrap().__repr__(), "datetime.timedelta(0)");
    assert!(!t.__bool__());
    let t = TimeDelta::new(1, 1, 500000).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (1, 1, 500000));
    assert_eq!(
        t.__repr__(),
        "datetime.timedelta(days=1, seconds=1, microseconds=500000)"
    );
    assert_eq!(t.__str__(), "1 day, 0:00:01.500000");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x40f5181800000000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-2, seconds=86398, microseconds=500000)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(0, 0, -1).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (-1, 86399, 999999));
    assert_eq!(
        t.__repr__(),
        "datetime.timedelta(days=-1, seconds=86399, microseconds=999999)"
    );
    assert_eq!(t.__str__(), "-1 day, 23:59:59.999999");
    assert_eq!(
        t.total_seconds().to_bits(),
        0xbeb0c6f7a0b5ed8d,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(microseconds=1)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(-1, 0, 0).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (-1, 0, 0));
    assert_eq!(t.__repr__(), "datetime.timedelta(days=-1)");
    assert_eq!(t.__str__(), "-1 day, 0:00:00");
    assert_eq!(
        t.total_seconds().to_bits(),
        0xc0f5180000000000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=1)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(2, 3661, 5).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (2, 3661, 5));
    assert_eq!(
        t.__repr__(),
        "datetime.timedelta(days=2, seconds=3661, microseconds=5)"
    );
    assert_eq!(t.__str__(), "2 days, 1:01:01.000005");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x41058a6800029f17,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-3, seconds=82738, microseconds=999995)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(0, 86400, 0).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (1, 0, 0));
    assert_eq!(t.__repr__(), "datetime.timedelta(days=1)");
    assert_eq!(t.__str__(), "1 day, 0:00:00");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x40f5180000000000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-1)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(0, -1, 0).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (-1, 86399, 0));
    assert_eq!(t.__repr__(), "datetime.timedelta(days=-1, seconds=86399)");
    assert_eq!(t.__str__(), "-1 day, 23:59:59");
    assert_eq!(
        t.total_seconds().to_bits(),
        0xbff0000000000000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(seconds=1)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(999999999, 86399, 999999).unwrap();
    assert_eq!(
        (t.days, t.seconds, t.microseconds),
        (999999999, 86399, 999999)
    );
    assert_eq!(
        t.__repr__(),
        "datetime.timedelta(days=999999999, seconds=86399, microseconds=999999)"
    );
    assert_eq!(t.__str__(), "999999999 days, 23:59:59.999999");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x42d3a52453c00000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap_err().message,
        "days=-1000000000; must have magnitude <= 999999999"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(-999999999, 0, 0).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (-999999999, 0, 0));
    assert_eq!(t.__repr__(), "datetime.timedelta(days=-999999999)");
    assert_eq!(t.__str__(), "-999999999 days, 0:00:00");
    assert_eq!(
        t.total_seconds().to_bits(),
        0xc2d3a524536ba000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=999999999)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(0, 0, 1).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (0, 0, 1));
    assert_eq!(t.__repr__(), "datetime.timedelta(microseconds=1)");
    assert_eq!(t.__str__(), "0:00:00.000001");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x3eb0c6f7a0b5ed8d,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-1, seconds=86399, microseconds=999999)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(0, 1, 0).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (0, 1, 0));
    assert_eq!(t.__repr__(), "datetime.timedelta(seconds=1)");
    assert_eq!(t.__str__(), "0:00:01");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x3ff0000000000000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-1, seconds=86399)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(1, 0, 0).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (1, 0, 0));
    assert_eq!(t.__repr__(), "datetime.timedelta(days=1)");
    assert_eq!(t.__str__(), "1 day, 0:00:00");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x40f5180000000000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-1)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(-1, 1, 0).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (-1, 1, 0));
    assert_eq!(t.__repr__(), "datetime.timedelta(days=-1, seconds=1)");
    assert_eq!(t.__str__(), "-1 day, 0:00:01");
    assert_eq!(
        t.total_seconds().to_bits(),
        0xc0f517f000000000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(seconds=86399)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(0, 3600, 0).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (0, 3600, 0));
    assert_eq!(t.__repr__(), "datetime.timedelta(seconds=3600)");
    assert_eq!(t.__str__(), "1:00:00");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x40ac200000000000,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-1, seconds=82800)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(0, 59, 999999).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (0, 59, 999999));
    assert_eq!(
        t.__repr__(),
        "datetime.timedelta(seconds=59, microseconds=999999)"
    );
    assert_eq!(t.__str__(), "0:00:59.999999");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x404dfffff79c8430,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-1, seconds=86340, microseconds=1)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(123456789, 12345, 678901).unwrap();
    assert_eq!(
        (t.days, t.seconds, t.microseconds),
        (123456789, 12345, 678901)
    );
    assert_eq!(
        t.__repr__(),
        "datetime.timedelta(days=123456789, seconds=12345, microseconds=678901)"
    );
    assert_eq!(t.__str__(), "123456789 days, 3:25:45.678901");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x42a3670dbebf735c,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-123456790, seconds=74054, microseconds=321099)"
    );
    assert!(t.__bool__());
    let t = TimeDelta::new(0, 0, 1234567890123).unwrap();
    assert_eq!((t.days, t.seconds, t.microseconds), (14, 24967, 890123));
    assert_eq!(
        t.__repr__(),
        "datetime.timedelta(days=14, seconds=24967, microseconds=890123)"
    );
    assert_eq!(t.__str__(), "14 days, 6:56:07.890123");
    assert_eq!(
        t.total_seconds().to_bits(),
        0x4132d687e3df19d6,
        "total_seconds of {}",
        t.__repr__()
    );
    assert_eq!(
        t.__neg__().unwrap().__repr__(),
        "datetime.timedelta(days=-15, seconds=61432, microseconds=109877)"
    );
    assert!(t.__bool__());
    let e = TimeDelta::new(1000000000, 0, 0).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::OverflowError,
            "days=1000000000; must have magnitude <= 999999999"
        )
    );
    let e = TimeDelta::new(-1000000000, 0, 0).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::OverflowError,
            "days=-1000000000; must have magnitude <= 999999999"
        )
    );
    let e = TimeDelta::new(999999999, 86400, 0).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::OverflowError,
            "days=1000000000; must have magnitude <= 999999999"
        )
    );
}

#[test]
fn arithmetic_matches_cpython() {
    let d = DateTime::new(2024, 2, 28, 23, 59, 59, 999999, None).unwrap();
    let t = TimeDelta::new(0, 0, 1).unwrap();
    assert_eq!(
        d.__add__(t).unwrap().__repr__(),
        "datetime.datetime(2024, 2, 29, 0, 0)"
    );
    assert_eq!(
        d.sub_delta(t).unwrap().__repr__(),
        "datetime.datetime(2024, 2, 28, 23, 59, 59, 999998)"
    );
    assert_eq!(d.__add__(t).unwrap().__sub__(&d).unwrap(), t);
    let d = DateTime::new(2024, 2, 29, 0, 0, 0, 0, None).unwrap();
    let t = TimeDelta::new(365, 0, 0).unwrap();
    assert_eq!(
        d.__add__(t).unwrap().__repr__(),
        "datetime.datetime(2025, 2, 28, 0, 0)"
    );
    assert_eq!(
        d.sub_delta(t).unwrap().__repr__(),
        "datetime.datetime(2023, 3, 1, 0, 0)"
    );
    assert_eq!(d.__add__(t).unwrap().__sub__(&d).unwrap(), t);
    let d = DateTime::new(2023, 2, 28, 0, 0, 0, 0, None).unwrap();
    let t = TimeDelta::new(1, 0, 0).unwrap();
    assert_eq!(
        d.__add__(t).unwrap().__repr__(),
        "datetime.datetime(2023, 3, 1, 0, 0)"
    );
    assert_eq!(
        d.sub_delta(t).unwrap().__repr__(),
        "datetime.datetime(2023, 2, 27, 0, 0)"
    );
    assert_eq!(d.__add__(t).unwrap().__sub__(&d).unwrap(), t);
    let d = DateTime::new(1, 1, 1, 0, 0, 0, 0, Some(TimeZone::UTC)).unwrap();
    let t = TimeDelta::new(3652058, 86399, 999999).unwrap();
    assert_eq!(
        d.__add__(t).unwrap().__repr__(),
        "datetime.datetime(9999, 12, 31, 23, 59, 59, 999999, tzinfo=datetime.timezone.utc)"
    );
    assert_eq!(
        d.sub_delta(t).unwrap_err().message,
        "date value out of range"
    );
    assert_eq!(d.__add__(t).unwrap().__sub__(&d).unwrap(), t);
    let d = DateTime::new(2000, 3, 1, 0, 0, 0, 0, None).unwrap();
    let t = TimeDelta::new(-1, 0, 0).unwrap();
    assert_eq!(
        d.__add__(t).unwrap().__repr__(),
        "datetime.datetime(2000, 2, 29, 0, 0)"
    );
    assert_eq!(
        d.sub_delta(t).unwrap().__repr__(),
        "datetime.datetime(2000, 3, 2, 0, 0)"
    );
    assert_eq!(d.__add__(t).unwrap().__sub__(&d).unwrap(), t);
    let d = DateTime::new(
        2024,
        1,
        2,
        3,
        4,
        5,
        123456,
        Some(TimeZone::new(TimeDelta::new(0, 19800, 0).unwrap()).unwrap()),
    )
    .unwrap();
    let t = TimeDelta::new(-1, 66600, 0).unwrap();
    assert_eq!(d.__add__(t).unwrap().__repr__(), "datetime.datetime(2024, 1, 1, 21, 34, 5, 123456, tzinfo=datetime.timezone(datetime.timedelta(seconds=19800)))");
    assert_eq!(d.sub_delta(t).unwrap().__repr__(), "datetime.datetime(2024, 1, 2, 8, 34, 5, 123456, tzinfo=datetime.timezone(datetime.timedelta(seconds=19800)))");
    assert_eq!(d.__add__(t).unwrap().__sub__(&d).unwrap(), t);
    let d = DateTime::new(1970, 1, 1, 0, 0, 0, 0, Some(TimeZone::UTC)).unwrap();
    let t = TimeDelta::new(-1, 86399, 0).unwrap();
    assert_eq!(
        d.__add__(t).unwrap().__repr__(),
        "datetime.datetime(1969, 12, 31, 23, 59, 59, tzinfo=datetime.timezone.utc)"
    );
    assert_eq!(
        d.sub_delta(t).unwrap().__repr__(),
        "datetime.datetime(1970, 1, 1, 0, 0, 1, tzinfo=datetime.timezone.utc)"
    );
    assert_eq!(d.__add__(t).unwrap().__sub__(&d).unwrap(), t);
    let (a, b) = (
        DateTime::new(2024, 3, 1, 0, 0, 0, 0, None).unwrap(),
        DateTime::new(2024, 2, 1, 0, 0, 0, 0, None).unwrap(),
    );
    assert_eq!(
        a.__sub__(&b).unwrap().__repr__(),
        "datetime.timedelta(days=29)"
    );
    assert_eq!(
        b.__sub__(&a).unwrap().__repr__(),
        "datetime.timedelta(days=-29)"
    );
    assert!(!(a == b));
    assert_eq!(a.partial_cmp(&b), Some(core::cmp::Ordering::Greater));
    let (a, b) = (
        DateTime::new(2024, 1, 1, 0, 0, 0, 0, Some(TimeZone::UTC)).unwrap(),
        DateTime::new(
            2024,
            1,
            1,
            5,
            30,
            0,
            0,
            Some(TimeZone::new(TimeDelta::new(0, 19800, 0).unwrap()).unwrap()),
        )
        .unwrap(),
    );
    assert_eq!(a.__sub__(&b).unwrap().__repr__(), "datetime.timedelta(0)");
    assert_eq!(b.__sub__(&a).unwrap().__repr__(), "datetime.timedelta(0)");
    assert!((a == b));
    assert_eq!(a.partial_cmp(&b), Some(core::cmp::Ordering::Equal));
    let (a, b) = (
        DateTime::new(1, 1, 1, 0, 0, 0, 0, None).unwrap(),
        DateTime::new(9999, 12, 31, 23, 59, 59, 999999, None).unwrap(),
    );
    assert_eq!(
        a.__sub__(&b).unwrap().__repr__(),
        "datetime.timedelta(days=-3652059, microseconds=1)"
    );
    assert_eq!(
        b.__sub__(&a).unwrap().__repr__(),
        "datetime.timedelta(days=3652058, seconds=86399, microseconds=999999)"
    );
    assert!(!(a == b));
    assert_eq!(a.partial_cmp(&b), Some(core::cmp::Ordering::Less));
    let (a, b) = (
        DateTime::new(
            2024,
            1,
            2,
            3,
            4,
            5,
            6,
            Some(TimeZone::new(TimeDelta::new(-1, 75600, 0).unwrap()).unwrap()),
        )
        .unwrap(),
        DateTime::new(2024, 1, 2, 3, 4, 5, 6, Some(TimeZone::UTC)).unwrap(),
    );
    assert_eq!(
        a.__sub__(&b).unwrap().__repr__(),
        "datetime.timedelta(seconds=10800)"
    );
    assert_eq!(
        b.__sub__(&a).unwrap().__repr__(),
        "datetime.timedelta(days=-1, seconds=75600)"
    );
    assert!(!(a == b));
    assert_eq!(a.partial_cmp(&b), Some(core::cmp::Ordering::Greater));
    let e = DateTime::new(9999, 12, 31, 0, 0, 0, 0, None)
        .unwrap()
        .__add__(TimeDelta::new(1, 0, 0).unwrap())
        .unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::OverflowError, "date value out of range")
    );
    let e = DateTime::new(1, 1, 1, 0, 0, 0, 0, None)
        .unwrap()
        .__add__(TimeDelta::new(-1, 86399, 999999).unwrap())
        .unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::OverflowError, "date value out of range")
    );
    let e = DateTime::from_ymd(2024, 1, 2)
        .unwrap()
        .__sub__(
            &DateTime::from_ymd(2024, 1, 2)
                .unwrap()
                .replace_tzinfo(Some(TimeZone::UTC)),
        )
        .unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::TypeError,
            "can't subtract offset-naive and offset-aware datetimes"
        )
    );
    assert!(
        DateTime::from_ymd(2024, 1, 2).unwrap()
            != DateTime::from_ymd(2024, 1, 2)
                .unwrap()
                .replace_tzinfo(Some(TimeZone::UTC))
    );
    assert_eq!(
        DateTime::from_ymd(2024, 1, 2).unwrap().partial_cmp(
            &DateTime::from_ymd(2024, 1, 2)
                .unwrap()
                .replace_tzinfo(Some(TimeZone::UTC))
        ),
        None
    );
    let d = DateTime::new(2024, 1, 2, 3, 4, 5, 6, Some(TimeZone::UTC)).unwrap();
    assert_eq!(d.astimezone(TimeZone::new(TimeDelta::new(0, 19800, 0).unwrap()).unwrap()).unwrap().__repr__(), "datetime.datetime(2024, 1, 2, 8, 34, 5, 6, tzinfo=datetime.timezone(datetime.timedelta(seconds=19800)))");
    assert_eq!(
        d.astimezone(TimeZone::new(TimeDelta::new(0, -10800, 0).unwrap()).unwrap())
            .unwrap()
            .__str__(),
        "2024-01-02 00:04:05.000006-03:00"
    );
    assert_eq!(d.utcoffset(), Some(TimeDelta::ZERO));
    assert_eq!(d.tzname().as_deref(), Some("UTC"));
    assert_eq!(d.replace_tzinfo(None).utcoffset(), None);
}

#[test]
fn timezone_matches_cpython() {
    let z = TimeZone::new(TimeDelta::new(0, 0, 0).unwrap()).unwrap();
    assert_eq!(z.__repr__(), "datetime.timezone.utc");
    assert_eq!(z.__str__(), "UTC");
    assert_eq!(z.tzname(), "UTC");
    let z = TimeZone::new(TimeDelta::new(0, 19800, 0).unwrap()).unwrap();
    assert_eq!(
        z.__repr__(),
        "datetime.timezone(datetime.timedelta(seconds=19800))"
    );
    assert_eq!(z.__str__(), "UTC+05:30");
    assert_eq!(z.tzname(), "UTC+05:30");
    let z = TimeZone::new(TimeDelta::new(-1, 75600, 0).unwrap()).unwrap();
    assert_eq!(
        z.__repr__(),
        "datetime.timezone(datetime.timedelta(days=-1, seconds=75600))"
    );
    assert_eq!(z.__str__(), "UTC-03:00");
    assert_eq!(z.tzname(), "UTC-03:00");
    let z = TimeZone::new(TimeDelta::new(0, 19815, 500000).unwrap()).unwrap();
    assert_eq!(
        z.__repr__(),
        "datetime.timezone(datetime.timedelta(seconds=19815, microseconds=500000))"
    );
    assert_eq!(z.__str__(), "UTC+05:30:15.500000");
    assert_eq!(z.tzname(), "UTC+05:30:15.500000");
    let z = TimeZone::new(TimeDelta::new(0, 86340, 0).unwrap()).unwrap();
    assert_eq!(
        z.__repr__(),
        "datetime.timezone(datetime.timedelta(seconds=86340))"
    );
    assert_eq!(z.__str__(), "UTC+23:59");
    assert_eq!(z.tzname(), "UTC+23:59");
    let z = TimeZone::new(TimeDelta::new(-1, 1, 0).unwrap()).unwrap();
    assert_eq!(
        z.__repr__(),
        "datetime.timezone(datetime.timedelta(days=-1, seconds=1))"
    );
    assert_eq!(z.__str__(), "UTC-23:59:59");
    assert_eq!(z.tzname(), "UTC-23:59:59");
    let e = TimeZone::new(TimeDelta::new(1, 0, 0).unwrap()).unwrap_err();
    assert_eq!((e.kind, e.message.as_str()), (ExcKind::ValueError, "offset must be a timedelta strictly between -timedelta(hours=24) and timedelta(hours=24), not datetime.timedelta(days=1)"));
    let e = TimeZone::new(TimeDelta::new(-1, 0, 0).unwrap()).unwrap_err();
    assert_eq!((e.kind, e.message.as_str()), (ExcKind::ValueError, "offset must be a timedelta strictly between -timedelta(hours=24) and timedelta(hours=24), not datetime.timedelta(days=-1)"));
    let e = TimeZone::new(TimeDelta::new(2, 0, 0).unwrap()).unwrap_err();
    assert_eq!((e.kind, e.message.as_str()), (ExcKind::ValueError, "offset must be a timedelta strictly between -timedelta(hours=24) and timedelta(hours=24), not datetime.timedelta(days=2)"));
    assert_eq!(TimeZone::new(TimeDelta::ZERO).unwrap(), TimeZone::UTC);
}

#[test]
fn constructor_errors_match_cpython() {
    let e = DateTime::new(0, 1, 1, 0, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::ValueError, "year must be in 1..9999, not 0")
    );
    let e = DateTime::new(10000, 1, 1, 0, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::ValueError, "year must be in 1..9999, not 10000")
    );
    let e = DateTime::new(2024, 0, 1, 0, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::ValueError, "month must be in 1..12, not 0")
    );
    let e = DateTime::new(2024, 13, 1, 0, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::ValueError, "month must be in 1..12, not 13")
    );
    let e = DateTime::new(2024, 2, 30, 0, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::ValueError,
            "day 30 must be in range 1..29 for month 2 in year 2024"
        )
    );
    let e = DateTime::new(2023, 2, 29, 0, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::ValueError,
            "day 29 must be in range 1..28 for month 2 in year 2023"
        )
    );
    let e = DateTime::new(2024, 4, 31, 0, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::ValueError,
            "day 31 must be in range 1..30 for month 4 in year 2024"
        )
    );
    let e = DateTime::new(2024, 1, 0, 0, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::ValueError,
            "day 0 must be in range 1..31 for month 1 in year 2024"
        )
    );
    let e = DateTime::new(2024, 1, 1, 24, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::ValueError, "hour must be in 0..23, not 24")
    );
    let e = DateTime::new(2024, 1, 1, -1, 0, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::ValueError, "hour must be in 0..23, not -1")
    );
    let e = DateTime::new(2024, 1, 1, 0, 60, 0, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::ValueError, "minute must be in 0..59, not 60")
    );
    let e = DateTime::new(2024, 1, 1, 0, 0, 60, 0, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (ExcKind::ValueError, "second must be in 0..59, not 60")
    );
    let e = DateTime::new(2024, 1, 1, 0, 0, 0, 1000000, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::ValueError,
            "microsecond must be in 0..999999, not 1000000"
        )
    );
    let e = DateTime::new(2024, 1, 1, 0, 0, 0, -1, None).unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::ValueError,
            "microsecond must be in 0..999999, not -1"
        )
    );
}

#[test]
fn arg_protocol() {
    let d = DateTime::new(2024, 1, 2, 3, 4, 5, 123456, Some(TimeZone::UTC)).unwrap();
    let a: Arg = d.into_arg();
    assert_eq!(a.type_name(), "datetime.datetime");
    assert_eq!(
        a.__repr__(),
        "datetime.datetime(2024, 1, 2, 3, 4, 5, 123456, tzinfo=datetime.timezone.utc)"
    );
    assert_eq!(
        laila::_compat::datetime::str_of(&a).unwrap(),
        "2024-01-02 03:04:05.123456+00:00"
    );
    assert_eq!(a.__getattr__("year").unwrap(), Arg::Int(2024));
    assert_eq!(a.__getattr__("month").unwrap(), Arg::Int(1));
    assert_eq!(a.__getattr__("day").unwrap(), Arg::Int(2));
    assert_eq!(a.__getattr__("hour").unwrap(), Arg::Int(3));
    assert_eq!(a.__getattr__("minute").unwrap(), Arg::Int(4));
    assert_eq!(a.__getattr__("second").unwrap(), Arg::Int(5));
    assert_eq!(a.__getattr__("microsecond").unwrap(), Arg::Int(123456));
    assert_eq!(a.__getattr__("fold").unwrap(), Arg::Int(0));
    assert_eq!(
        a.__getattr__("tzinfo").unwrap().__repr__(),
        "datetime.timezone.utc"
    );
    assert_eq!(
        d.replace_tzinfo(None)
            .into_arg()
            .__getattr__("tzinfo")
            .unwrap(),
        Arg::None
    );
    let e = a.__getattr__("nope").unwrap_err();
    assert_eq!(
        (e.kind, e.message.as_str()),
        (
            ExcKind::AttributeError,
            "'datetime.datetime' object has no attribute 'nope'"
        )
    );
    let e = a.__len__().unwrap_err();
    assert_eq!(e.message, "object of type 'datetime.datetime' has no len()");
    // equality through Arg: same instant in another zone is ==, naive is not
    let same = d
        .astimezone(TimeZone::new(TimeDelta::new(0, 19800, 0).unwrap()).unwrap())
        .unwrap()
        .into_arg();
    assert!(a == same);
    assert_eq!(a.__hash__().unwrap(), same.__hash__().unwrap());
    assert!(a != d.replace_tzinfo(None).into_arg());
    assert!(a != Arg::Int(1));
    assert!(laila::python::builtins::isinstance::<DateTime>(&a));
    assert!(!laila::python::builtins::isinstance::<TimeDelta>(&a));
    assert_eq!(a.downcast_ref::<DateTime>().unwrap().year, 2024);
    // dict key: hashable
    let m = laila::python::builtins::dict(laila::python::Args::new()).unwrap();
    m.__setitem__(a.clone(), 1).unwrap();
    assert_eq!(m.__getitem__(same).unwrap(), Arg::Int(1));
    let t: Arg = TimeDelta::new(1, 1, 500000).unwrap().into_arg();
    assert_eq!(t.type_name(), "datetime.timedelta");
    assert_eq!(
        t.__repr__(),
        "datetime.timedelta(days=1, seconds=1, microseconds=500000)"
    );
    assert_eq!(
        laila::_compat::datetime::str_of(&t).unwrap(),
        "1 day, 0:00:01.500000"
    );
    assert_eq!(t.__getattr__("days").unwrap(), Arg::Int(1));
    assert_eq!(t.__getattr__("seconds").unwrap(), Arg::Int(1));
    assert_eq!(t.__getattr__("microseconds").unwrap(), Arg::Int(500000));
    assert!(t == TimeDelta::new(0, 86401, 500000).unwrap().into_arg());
    let z: Arg = TimeZone::UTC.into_arg();
    assert_eq!(z.type_name(), "datetime.timezone");
    assert_eq!(z.__repr__(), "datetime.timezone.utc");
    assert_eq!(laila::_compat::datetime::str_of(&z).unwrap(), "UTC");
    assert!(z == TimeZone::new(TimeDelta::ZERO).unwrap().into_arg());
    assert!(z.__hash__().is_ok());
}

#[test]
fn calendar_helpers() {
    use laila::_compat::datetime::{
        civil_from_days, days_from_civil, days_in_month, is_leap, weekday, ymd_to_ord,
    };
    assert_eq!(days_from_civil(1970, 1, 1), 0);
    assert_eq!(civil_from_days(0), (1970, 1, 1));
    assert_eq!(ymd_to_ord(1970, 1, 1), 719163);
    assert_eq!(weekday(1970, 1, 1), 3);
    assert_eq!(days_from_civil(1, 1, 1), -719162);
    assert_eq!(civil_from_days(-719162), (1, 1, 1));
    assert_eq!(ymd_to_ord(1, 1, 1), 1);
    assert_eq!(weekday(1, 1, 1), 0);
    assert_eq!(days_from_civil(9999, 12, 31), 2932896);
    assert_eq!(civil_from_days(2932896), (9999, 12, 31));
    assert_eq!(ymd_to_ord(9999, 12, 31), 3652059);
    assert_eq!(weekday(9999, 12, 31), 4);
    assert_eq!(days_from_civil(2000, 2, 29), 11016);
    assert_eq!(civil_from_days(11016), (2000, 2, 29));
    assert_eq!(ymd_to_ord(2000, 2, 29), 730179);
    assert_eq!(weekday(2000, 2, 29), 1);
    assert_eq!(days_from_civil(1900, 3, 1), -25508);
    assert_eq!(civil_from_days(-25508), (1900, 3, 1));
    assert_eq!(ymd_to_ord(1900, 3, 1), 693655);
    assert_eq!(weekday(1900, 3, 1), 3);
    assert_eq!(days_from_civil(2024, 2, 29), 19782);
    assert_eq!(civil_from_days(19782), (2024, 2, 29));
    assert_eq!(ymd_to_ord(2024, 2, 29), 738945);
    assert_eq!(weekday(2024, 2, 29), 3);
    assert_eq!(days_from_civil(1600, 2, 29), -135081);
    assert_eq!(civil_from_days(-135081), (1600, 2, 29));
    assert_eq!(ymd_to_ord(1600, 2, 29), 584082);
    assert_eq!(weekday(1600, 2, 29), 1);
    assert_eq!(days_from_civil(400, 1, 1), -573431);
    assert_eq!(civil_from_days(-573431), (400, 1, 1));
    assert_eq!(ymd_to_ord(400, 1, 1), 145732);
    assert_eq!(weekday(400, 1, 1), 5);
    // proleptic years outside Python's range round-trip too
    for z in [-1_000_000i64, -719_163, -719_162, -1, 0, 1, 10_000_000] {
        let (y, m, d) = civil_from_days(z);
        assert_eq!(days_from_civil(y, m, d), z);
    }
    assert!(!is_leap(1900));
    assert_eq!(days_in_month(1900, 2), 28);
    assert!(is_leap(2000));
    assert_eq!(days_in_month(2000, 2), 29);
    assert!(is_leap(2024));
    assert_eq!(days_in_month(2024, 2), 29);
    assert!(!is_leap(2023));
    assert_eq!(days_in_month(2023, 2), 28);
    assert!(!is_leap(2100));
    assert_eq!(days_in_month(2100, 2), 28);
    assert!(is_leap(1600));
    assert_eq!(days_in_month(1600, 2), 29);
    assert!(is_leap(4));
    assert_eq!(days_in_month(4, 2), 29);
}
